window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-eaca1cbe1fe241ab"]={"versions": [{"id": "FIG-eaca1cbe1fe241ab", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Aktivitätsdiagramm (Kontrollfluss-/Ablaufdiagramm einer synchronen Bibliotheksfunktion).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses der Funktion <code>E2E_P22Forward()</code> innerhalb des <strong>AUTOSAR E2E-Protokolls (Profil 22)</strong>.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Komponente: <strong>E2E Library / E2E Protocol</strong> (Classic Platform und Adaptive Platform / Foundation).</li>\n<li>Profil 22 ist für ASIL-D-fähige Kommunikation über serielle Busse/Netzwerke (z. B. CAN-FD, FlexRay, Ethernet) ausgelegt.</li>\n<li>Die <code>Forward</code>-Variante wird typischerweise in Gateway-Knoten, Routern oder Zwischenstationen (z. B. PduR, Safety-Gateways) eingesetzt, um empfangene und vorab geprüfte Daten weiterzuleiten, den Sequenzzähler (<code>Counter</code>) fortzuschreiben und die Prüfsumme (<code>CRC</code>) unter Berücksichtigung des Weiterleitungsstatus konsistent neu zu berechnen, ohne die Payload selbst applikativ neu zu generieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionssignatur:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>E2E_P22Forward(Config, State, Data, Length, ForwardStatus)</code> <em>(im Schaubild als Tippfehler der Spezifikation: <code>FowardStatus</code>)</em>.</p>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Parameter & Datenstrukturen:</strong></li>\n<li><code>Config</code> (<code>const E2E_P22ConfigType*</code>): Zeiger auf die statische Konfiguration (u. a. <code>DataID</code>, <code>DataLength</code>, Bit-/Byte-Offsets für CRC und Counter).</li>\n<li><code>State</code> (<code>E2E_P22ProtectStateType<em></code> / <code>E2E_P22ForwardStateType</em></code>): Zeiger auf den dynamischen Zustand (enthält u. a. den aktuellen Zählerstand <code>Counter</code>).</li>\n<li><code>Data</code> (<code>uint8*</code>): In/Out-Zeiger auf den linearen PDU-Datenpuffer, in den Zähler und Prüfsumme direkt (in-place) serialisiert werden.</li>\n<li><code>Length</code> (<code>uint16</code> / <code>uint32</code>): Effektive Länge der zu verarbeitenden Nutzdaten in Bytes.</li>\n<li><code>ForwardStatus</code> (<code>E2E_PCheckStatusType</code> bzw. Forward-Status-Enumeration): Status der vorangegangenen Prüffunktion (<code>E2E_P22Check</code>), um festzulegen, wie fehlerhafte oder wiederholte Pakete bei der Weiterleitung behandelt werden.</li>\n<li><strong>Modellierte Kontrollflusselemente:</strong></li>\n<li>Initial Node (Startknoten).</li>\n<li>Fünf sequenzierte Aktionsknoten (Action Nodes) mit Verfeinerungssymbol (Sub-Aktivität):</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Increment Counter</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li>Verzweigungen mit Guards: <code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code>.</li>\n<li>Drei Activity Final Nodes (Endknoten mit Rückgabewerten <code>E2E_E_INPUTERR_NULL</code>, <code>E2E_E_INPUTERR_WRONG</code>, <code>E2E_E_OK</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erfolgt strikt synchron, reentrant und deterministisch innerhalb des Aufrufer-Threads:</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Parametervalidierung (<code>Verify inputs of the protect function</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung auf ungültige Zeiger (<code>Config == NULL</code>, <code>State == NULL</code>, <code>Data == NULL</code>).</li>\n<li>Zweig <code>[null input]</code>: Unmittelbarer Abbruch $\\rightarrow$ Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Prüfung auf Konsistenz und Wertebereiche (z. B. <code>Length</code>-Validierung gegen <code>Config-&gt;DataLength</code>, Offset-Bereiche innerhalb der PDU-Grenzen).</li>\n<li>Zweig <code>[wrong input]</code>: Unmittelbarer Abbruch $\\rightarrow$ Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Gutfall-Pfad (<code>[input ok]</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>Increment Counter</code>:</strong> Der im <code>State</code> gekapselte Sequenzzähler wird zyklisch inkrementiert (Modulo-Arithmetik gemäß Profil-22-Spezifikation).</li>\n<li><strong><code>Write Counter</code>:</strong> Der neue Zählerwert wird an der in <code>Config</code> definierten Bit- und Byte-Position in den <code>Data</code>-Puffer geschrieben.</li>\n<li><strong><code>Compute CRC</code>:</strong> Berechnung der CRC-8 (Polynom 0x2F / SAE J1850 bzw. profilspezifisch) über den <code>Data</code>-Puffer und die DataID.</li>\n<li><strong><code>Write CRC</code>:</strong> Die berechnete Prüfsumme wird an der in <code>Config</code> definierten Position in das <code>Data</code>-Array geschrieben.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Terminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückgabe des Statuscodes <code>E2E_E_OK</code> an den Aufrufer.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>In-Place-Modifikation & Pufferverwaltung:</strong> <code>Data</code> wird direkt manipuliert. Der aufrufende Gateway-/Stack-Treiber muss sicherstellen, dass der Puffer beschreibbar ist und nicht parallel von einem DMA- oder Interrupt-Kontext gelesen oder überschrieben wird (Race-Condition-Vermeidung).</li>\n<li><strong>Fehlerbehandlung (Error Handling):</strong></li>\n<li>Tritt <code>E2E_E_INPUTERR_NULL</code> oder <code>E2E_E_INPUTERR_WRONG</code> auf, verbleibt der Datenpuffer unverändert bzw. in undefiniertem E2E-Zustand. Der Aufrufer (z. B. PduR / Safety-Wrapper) darf die PDU unter keinen Umständen weiterleiten (PDU Drop) und muss ggf. <code>Det_ReportError</code> aufrufen.</li>\n<li><strong>Forwarding-Semantik vs. Protect:</strong></li>\n<li>Im Gateway-Betrieb verhindert <code>Forward</code>, dass bei verfälschten oder verloren gegangenen Eingangs-PDUs blind ein neuer, fehlerfreier Schutzstatus erzeugt wird. Die Implementierung muss <code>ForwardStatus</code> normativ berücksichtigen (z. B. gezielte Korrumpierung oder Unterdrückung bei fehlerhaftem Eingangsstatus, um Safety-Integritätslücken zu verhindern).</li>\n<li><strong>Laufzeit & Safety-Qualifizierung:</strong></li>\n<li>Die Funktion ist blockierungsfrei, frei von dynamischer Speicherallokation und verfügt über eine statisch begrenzte Worst-Case Execution Time (WCET), wie für ASIL-D-Softwareeinheiten nach ISO 26262 Teil 6 gefordert.</li>\n</ul>"}, {"id": "FIG-f0e37e1b867aa289", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Aktivitätsdiagramm (Kontrollfluss-/Ablaufdiagramm einer synchronen Bibliotheksfunktion).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses der Funktion <code>E2E_P22Forward()</code> innerhalb des <strong>AUTOSAR E2E-Protokolls (Profil 22)</strong>.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Komponente: <strong>E2E Library / E2E Protocol</strong> (Classic Platform und Adaptive Platform / Foundation).</li>\n<li>Profil 22 ist für ASIL-D-fähige Kommunikation über serielle Busse/Netzwerke (z. B. CAN-FD, FlexRay, Ethernet) ausgelegt.</li>\n<li>Die <code>Forward</code>-Variante wird typischerweise in Gateway-Knoten, Routern oder Zwischenstationen (z. B. PduR, Safety-Gateways) eingesetzt, um empfangene und vorab geprüfte Daten weiterzuleiten, den Sequenzzähler (<code>Counter</code>) fortzuschreiben und die Prüfsumme (<code>CRC</code>) unter Berücksichtigung des Weiterleitungsstatus konsistent neu zu berechnen, ohne die Payload selbst applikativ neu zu generieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionssignatur:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>E2E_P22Forward(Config, State, Data, Length, FowardStatus)</code> <em>(mit Tippfehler in der Spezifikationsgrafik: <code>FowardStatus</code>)</em>.</p>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Parameter & Datenstrukturen:</strong></li>\n<li><code>Config</code>: Zeiger auf die statische Konfiguration.</li>\n<li><code>State</code>: Zeiger auf die dynamische Zustandsstruktur.</li>\n<li><code>Data</code>: In/Out-Zeiger auf den Nutzdatenpuffer.</li>\n<li><code>Length</code>: Länge der Nutzdaten.</li>\n<li><code>ForwardStatus</code> (<code>FowardStatus</code>): Statuswert der vorangegangenen Prüffunktion.</li>\n<li><strong>Modellierte Kontrollflusselemente:</strong></li>\n<li>Initial Node (Startknoten).</li>\n<li>Sieben sequenzierte Aktionsknoten (Action Nodes) mit Verfeinerungssymbol (Sub-Aktivität):</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Compute CRC - DataID</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li>Verzweigung mit Guards: <code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code>.</li>\n<li>Drei Activity Final Nodes (Endknoten mit Rückgabewerten <code>return E2E_E_INPUTERR_NULL</code>, <code>return E2E_E_INPUTERR_WRONG</code>, <code>return E2E_E_OK</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft synchron und deterministisch:</p>\n<ol class=\"fig-list\">\n<li><strong>Eingangsvalidierung (<code>Verify inputs of the protect function</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung auf NULL-Zeiger (<code>[null input]</code>): Verzweigung zum linken Endknoten mit Rückgabe <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Prüfung auf ungültige Parameterwerte (<code>[wrong input]</code>): Verzweigung zum rechten Endknoten mit Rückgabe <code>E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Gutfall-Pfad (<code>[input ok]</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>Compute offset</code>:</strong> Ermittlung der relativen Bit-/Byte-Offsets innerhalb der Nutzdaten.</li>\n<li><strong><code>Write Counter</code>:</strong> Der aktuelle Zählerstand aus <code>State</code> wird in den Datenpuffer geschrieben.</li>\n<li><strong><code>Compute CRC</code>:</strong> Berechnung der Prüfsumme über die Nutzdaten.</li>\n<li><strong><code>Compute CRC - DataID</code>:</strong> Einrechnung der DataID in die Prüfsummenberechnung.</li>\n<li><strong><code>Write CRC</code>:</strong> Die berechnete Prüfsumme wird in den Datenpuffer eingetragen.</li>\n<li><strong><code>Increment Counter</code>:</strong> Der Zählerstand im Zustandsübertrag wird für die nachfolgende Ausführung inkrementiert.</li>\n<li>Übergang zum mittleren Endknoten mit Rückgabe <code>E2E_E_OK</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Verbindlichkeit:</strong> Die Reihenfolge der Aktionsknoten definiert den verbindlichen Kontroll- und Datenfluss der Funktion <code>E2E_P22Forward</code>.</li>\n<li><strong>Implementierungsaspekte:</strong></li>\n<li>Vor dem Beschreiben der Nutzdaten wird der Offset dynamisch ermittelt (<code>Compute offset</code>).</li>\n<li>Der Zählerstand wird zunächst in den Puffer geschrieben und erst ganz am Ende nach erfolgreicher Schutzdaten-Serialisierung (<code>Write CRC</code>) für den nächsten Zyklus inkrementiert (<code>Increment Counter</code>).</li>\n<li>Die CRC-Berechnung ist zweistufig strukturiert (<code>Compute CRC</code> gefolgt von <code>Compute CRC - DataID</code>).</li>\n</ul>"}, {"id": "FIG-fd42b02a5041c0bc", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Aktivitätsdiagramm (Kontrollfluss-/Ablaufdiagramm einer synchronen Bibliotheksfunktion).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses der Funktion <code>E2E_P22Forward()</code> innerhalb des <strong>AUTOSAR E2E-Protokolls (Profil 22)</strong>.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Komponente: <strong>E2E Library / E2E Protocol</strong> (Classic Platform und Adaptive Platform / Foundation).</li>\n<li>Profil 22 ist für ASIL-D-fähige Kommunikation über serielle Busse/Netzwerke (z. B. CAN-FD, FlexRay, Ethernet) ausgelegt.</li>\n<li>Die <code>Forward</code>-Variante wird typischerweise in Gateway-Knoten, Routern oder Zwischenstationen (z. B. PduR, Safety-Gateways) eingesetzt, um empfangene und vorab geprüfte Daten weiterzuleiten, den Sequenzzähler (<code>Counter</code>) fortzuschreiben und die Prüfsumme (<code>CRC</code>) unter Berücksichtigung des Weiterleitungsstatus konsistent neu zu berechnen, ohne die Payload selbst applikativ neu zu generieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionssignatur:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>E2E_P22Forward(Config, Length, FowardStatus, State, Data)</code> <em>(mit Tippfehler in der Spezifikationsgrafik: <code>FowardStatus</code>)</em>.</p>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Parameter & Datenstrukturen:</strong></li>\n<li><code>Config</code>: Zeiger auf die statische Konfiguration.</li>\n<li><code>Length</code>: Länge der Nutzdaten.</li>\n<li><code>ForwardStatus</code> (<code>FowardStatus</code>): Statuswert der vorangegangenen Prüffunktion.</li>\n<li><code>State</code>: Zeiger auf die dynamische Zustandsstruktur.</li>\n<li><code>Data</code>: In/Out-Zeiger auf den Nutzdatenpuffer.</li>\n<li><strong>Modellierte Kontrollflusselemente:</strong></li>\n<li>Initial Node (Startknoten).</li>\n<li>Sieben sequenzierte Aktionsknoten (Action Nodes) mit Verfeinerungssymbol (Sub-Aktivität):</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Compute CRC - DataID</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li>Verzweigung mit Guards: <code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code>.</li>\n<li>Drei Activity Final Nodes (Endknoten mit Rückgabewerten <code>return E2E_E_INPUTERR_NULL</code>, <code>return E2E_E_INPUTERR_WRONG</code>, <code>return E2E_E_OK</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft synchron und deterministisch:</p>\n<ol class=\"fig-list\">\n<li><strong>Eingangsvalidierung (<code>Verify inputs of the protect function</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung auf NULL-Zeiger (<code>[null input]</code>): Verzweigung zum linken Endknoten mit Rückgabe <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Prüfung auf ungültige Parameterwerte (<code>[wrong input]</code>): Verzweigung zum rechten Endknoten mit Rückgabe <code>E2E_E_INPUTERR_WRONG</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Gutfall-Pfad (<code>[input ok]</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>Compute offset</code>:</strong> Ermittlung der relativen Bit-/Byte-Offsets innerhalb der Nutzdaten.</li>\n<li><strong><code>Write Counter</code>:</strong> Der aktuelle Zählerstand aus <code>State</code> wird in den Datenpuffer geschrieben.</li>\n<li><strong><code>Compute CRC</code>:</strong> Berechnung der Prüfsumme über die Nutzdaten.</li>\n<li><strong><code>Compute CRC - DataID</code>:</strong> Einrechnung der DataID in die Prüfsummenberechnung.</li>\n<li><strong><code>Write CRC</code>:</strong> Die berechnete Prüfsumme wird in den Datenpuffer eingetragen.</li>\n<li><strong><code>Increment Counter</code>:</strong> Der Zählerstand im Zustandsübertrag wird für die nachfolgende Ausführung inkrementiert.</li>\n<li>Übergang zum mittleren Endknoten mit Rückgabe <code>E2E_E_OK</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Verbindlichkeit:</strong> Die Reihenfolge der Aktionsknoten definiert den verbindlichen Kontroll- und Datenfluss der Funktion <code>E2E_P22Forward</code>.</li>\n<li><strong>Implementierungsaspekte:</strong></li>\n<li>Vor dem Beschreiben der Nutzdaten wird der Offset dynamisch ermittelt (<code>Compute offset</code>).</li>\n<li>Der Zählerstand wird zunächst in den Puffer geschrieben und erst ganz am Ende nach erfolgreicher Schutzdaten-Serialisierung (<code>Write CRC</code>) für den nächsten Zyklus inkrementiert (<code>Increment Counter</code>).</li>\n<li>Die CRC-Berechnung ist zweistufig strukturiert (<code>Compute CRC</code> gefolgt von <code>Compute CRC - DataID</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-eaca1cbe1fe241ab", "to": "FIG-f0e37e1b867aa289", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kontrollfluss und Aktionsfolge grundlegend umstrukturiert:</li>\n<li>Aktion <code>Increment Counter</code> von der Position vor <code>Write Counter</code> an das Ende des Gutfall-Pfads nach <code>Write CRC</code> verschoben.</li>\n<li>Aktion <code>Compute offset</code> nach der Verzweigung <code>[input ok]</code> vor <code>Write Counter</code> neu eingefügt.</li>\n<li>Aktion <code>Compute CRC - DataID</code> im Ablauf nach <code>Compute CRC</code> und vor <code>Write CRC</code> neu eingefügt.</li>\n</ul>"}, {"from": "FIG-f0e37e1b867aa289", "to": "FIG-fd42b02a5041c0bc", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Funktionssignatur am Startknoten: Parameterreihenfolge von <code>E2E_P22Forward(Config, State, Data, Length, FowardStatus)</code> geändert zu <code>E2E_P22Forward(Config, Length, FowardStatus, State, Data)</code>.</li>\n</ul>"}]};
